if(b.source.canonicalSha!=='2bcbe30ac2b4e2a64a159f121dc818f961fe7c15'||b.cases['B3.1'].attempts.some(a=>a.turns.length!==3||a.turns.some(t=>t.transportStatus!=='COMPLETE')))throw new Error('Exact stopped independent batch required');
