const rows=[];
for(const [id,c] of Object.entries(b.cases).filter(([id])=>id==='B3.1'))for(const a of c.attempts){
 const final=a.turns.at(-1),session=jsonl(final.sessionSnapshot),calls=new Map(),returns=[];
 for(const r of session){const p=r.event.payload;if(r.event.type!=='response_item')continue;
  if(['custom_tool_call','function_call'].includes(p.type))calls.set(p.call_id,{line:r.line,name:p.name,input:p.input??p.arguments});
  if(!['custom_tool_call_output','function_call_output'].includes(p.type))continue;
  const texts=typeof p.output==='string'?[p.output]:(p.output??[]).filter(v=>typeof v.text==='string').map(v=>v.text);
  for(let part=0;part<texts.length;part++){const text=texts[part],decoded=[];for(const m of text.matchAll(/"(?:[^"\\]|\\.)*"/g)){try{const v=JSON.parse(m[0]);if(typeof v==='string'&&v.includes('Exit code:'))decoded.push(v);}catch{}}
   const variants=[text,...decoded],bodies=(decoded.length?decoded:[text]).filter(v=>v.includes('Exit code: 0')&&v.includes('Output:')).map(v=>v.slice(v.indexOf('Output:')+7).replace(/^\r?\n/,'').replace(/\r\n/g,'\n'));
   returns.push({line:r.line,callId:p.call_id,part,call:calls.get(p.call_id)??null,rawTextSha256:sha(Buffer.from(text)),truncated:/truncated output|tokens (?:truncated|omitted)/i.test(text),texts:variants,bodies});
  }
 }
 const resources=['skills/guide/SKILL.md','skills/guide/references/guide-framework.md','skills/guide/references/interaction-design.md'];
 const proofs=resources.map(rel=>{const file=path.join(b.cacheRoot,rel),source=fs.readFileSync(file,'utf8'),value=norm(source),escaped=JSON.stringify(value).slice(1,-1);const whole=returns.filter(r=>r.texts.some(t=>norm(t).includes(value)||t.includes(escaped))).map(r=>({sessionLine:r.line,callId:r.callId,part:r.part,callLine:r.call?.line,toolName:r.call?.name,rawTextSha256:r.rawTextSha256,hasTruncationMarker:r.truncated,fullBodyDespiteMarker:true}));const concat=[];
  for(const callId of new Set(returns.map(r=>r.callId))){const group=returns.filter(r=>r.callId===callId&&!r.truncated);if(!group.some(r=>/Select-Object/.test(r.call?.input??'')))continue;const bodies=group.flatMap(r=>r.bodies);const combined=bodies.join('');if(norm(combined)===value)concat.push({callId,callLine:group[0].call?.line,sessionLines:group.map(r=>r.line),parts:group.map(r=>r.part),method:'Actual same-call shell-read chunk bodies concatenated in received order',normalizedBodySha256:sha(Buffer.from(norm(combined))),cacheNormalizedBodySha256:sha(Buffer.from(value)),exactNormalizedCompleteBody:true});}
  return {relative:rel,cacheRawSha256:sha(fs.readFileSync(file)),actualWholeToolContextBody:whole.length>0,actualFullSameSessionChunkBody:concat.length>0,wholeBodyEvidence:whole,chunkEvidence:concat};});
 const material=fs.readFileSync(c.material,'utf8'),mv=norm(material);const mat=returns.filter(r=>r.texts.some(t=>norm(t).includes(mv)||t.includes(JSON.stringify(mv).slice(1,-1)))).map(r=>({sessionLine:r.line,callId:r.callId,part:r.part,rawTextSha256:r.rawTextSha256,hasTruncationMarker:r.truncated}));
 rows.push({variant:id,attemptId:a.attemptId,uuid:a.threadId,actualTurns:a.turns.length,finalSession:final.sessionSnapshot,sessionRawSha256:sha(fs.readFileSync(final.sessionSnapshot)),actualToolNames:[...new Set([...calls.values()].map(c=>c.name))],originalTruncatedReturns:returns.filter(r=>r.truncated).map(r=>({sessionLine:r.line,callId:r.callId,part:r.part,callLine:r.call?.line,rawTextSha256:r.rawTextSha256})),resources:proofs,material:{file:c.material,rawSha256:sha(fs.readFileSync(c.material)),actualWholeContextReceived:mat.length>0,evidence:mat}});
}
const report={schemaVersion:1,recordedAt:new Date().toISOString(),reviewer:'/root/behavior_014_b',method:'independent_actual_session_tool_return_full_content_match',canonical:b.source,batchFile,rows,noCliStdoutSubstitution:true,noModelClaimUsedAsReadProof:true,noModelInstallGradeInvocation:true,noOriginalMutation:true};
const out=path.join(dir,'model-context-resource-read-corrected.json');fs.writeFileSync(out,JSON.stringify(report,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({out,sha256:sha(fs.readFileSync(out)),rows:rows.map(r=>({variant:r.variant,uuid:r.uuid,truncatedReturns:r.originalTruncatedReturns.length,resources:r.resources.map(p=>({rel:p.relative,whole:p.actualWholeToolContextBody,chunks:p.actualFullSameSessionChunkBody})),material:r.material.actualWholeContextReceived}))},null,2));

